import React from 'react'
import { useState, useEffect, useMemo } from 'react';
import Test1 from '@/pages/Test1'
import TestChild from '@/pages/TestChild'
import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'
import { useRouter, useRoute, RouterLink, RouterView } from '@/router'


const Test = () => {
    const router = useRouter() 
    const route = useRoute()
    const [routerInfor, setRouterInfor] = useState("");
    const [count, setCount] = useState(0);
    const [array1, setArr1] = useState([
        { name: "tuyen", age: 12 },
        { name: "duong", age: 30 },
    ])
    const [messageFromChild, SetMessage] = useState("");

    const [bienNeedWatch, SetBienNeedWatch] = useState("");
    const [bienNeedComputed, SetBienNeedComputed] = useState("");

    const testMessage = useAppSelector(getters.testMessage)
    const dispatch = useAppDispatch()


    const getCurrentDateTime = () => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0'); // Tháng tính từ 0 nên cần +1
        const dd = String(now.getDate()).padStart(2, '0');
        const hh24 = String(now.getHours()).padStart(2, '0');   // Giờ định dạng 24h
        const mi = String(now.getMinutes()).padStart(2, '0'); // Phút
        const ss = String(now.getSeconds()).padStart(2, '0'); // Giây
        const sss = String(now.getMilliseconds()).padStart(3, '0'); // Mili-giây (3 chữ số)

        // Trả về định dạng: yyyy/mm/dd hh24:mi:ss.sss
        return `${yyyy}/${mm}/${dd} ${hh24}:${mi}:${ss}.${sss}`;
    }

    const SetCount = () => {
        setCount(count + 1);
    }
    const SetArray = () => {

        let array = [...array1]
        array.push({ name: "tuyen1", age: 12 })
        setArr1(array);
    }

    const GetValueFromChild = (message) => {
        SetMessage(message)
    }
    const ChangeStateTestMess = () => {
        let curDT = getCurrentDateTime();
        dispatch(mutations.setTestMessage(curDT))
    }

    const TriggerWatch = () => {
        let curDT = getCurrentDateTime();
        SetBienNeedWatch(curDT);
    }

    // Tương tự watch trong Vue
    useEffect(() => {
        if (bienNeedWatch)
            alert(`đã chạy watch theo dõi thay đổi, giá trị mới:${bienNeedWatch}`);
    }, [bienNeedWatch]); // Mảng dependency: chỉ chạy lại khi biến 'bienNeedWatch' thay đổi


    const TriggerComputed = () => {
        let curDT = getCurrentDateTime();
        SetBienNeedComputed(curDT);
    }


    // Tương tự computed: Chỉ chạy lại hàm này  khi  'bienNeedComputed' thay đổi.
    const GetBienNeedComputed = useMemo(() => {
        console.log("Đang tính toán lại bienNeedComputed ..." + bienNeedComputed);
        // some logic here 
        return "Đã thay đổi:" + bienNeedComputed;
    }, [bienNeedComputed]); // Mảng dependency



    const GetInforCurrentRouter=()=>{
          setRouterInfor(JSON.stringify(route)) ;
    }

    const MovetoOtherRoute=()=>{
        router.push('/readme')
    }

    return (
        <>
            <p>Thử tính chất reactive:</p>
            <p> Giá trị:{count}</p>
            <button onClick={SetCount}> Make count </button>
            <p>.....................................</p>
            <p>Thử chuyền prop từ cpn cha vào cpn con </p>
            <Test1 message={'hello im message'} message1={'hello im message1'} />
            <p>.....................................</p>
            <p>Thử vòng for</p>
            {array1.map((item, index) =>
            (
                <p key={index}> <span>name:{item.name}</span> <span>age:{item.age}</span></p>
            )
            )}
            <button onClick={SetArray}> Thêm phần tử vào for</button>
            <p>.....................................</p>
            <p>Thử chuyền dữ liệu từ CPN con sang CPN cha</p>
            <p>Giá trị cpn con chuyền sang:{messageFromChild}</p>
            <TestChild onSendDataToParent={GetValueFromChild} />
            <p>.....................................</p>
            <p>Thử set/get biến state của store/state</p>
            <p>Giá trị biến state(testMessage):{testMessage} </p>
            <button onClick={ChangeStateTestMess} > Thay đổi state(testMessage) </button>
            <p>.....................................</p>
            <p>Theo dõi sự thay đổi giá trị của 1 biến state/prop sử dụng useEffect-tương tự watch trong Vuejs</p>
            <p>Giá trị đang theo dõi thay đổi: {bienNeedWatch} </p>
            <button onClick={TriggerWatch}>Trigger thay đổi</button>
            <p>.....................................</p>
            <p>Thử dùng useMemo- tương tự computed trong Vue js</p>
            <p>Giá trị đang theo dõi thay đổi: {GetBienNeedComputed} </p>
            <button onClick={TriggerComputed}>Trigger thay đổi</button>
            <p>.....................................</p>
            <p>Thử router</p>
            <p>Các thông tin của router hiện tại:{routerInfor}</p>
            <button onClick={GetInforCurrentRouter } >Get infor router </button>
            <button onClick={MovetoOtherRoute } >Move to other router</button>
          
        </>
    )
}
export default Test;