import React from 'react'
import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'

const Test1=({message,message1})=>{
  const testMessage  = useAppSelector(getters.testMessage)
    return (
       <>
        <p>message:{message}</p>
        <p>message1:{message1}</p>
        <p>Giá trị biến state(testMessage) get ở CPN khác:{testMessage} </p>
       </>

    )
}

export default Test1;