import React from 'react'

const TestChild=({onSendDataToParent})=>{
 
    const HandleSendDataToParent =()=>{
        onSendDataToParent("Hello parent") ;
    }
    return (
       <>
        <button onClick={HandleSendDataToParent} >Gửi giá trị sang cpn cha</button>
       </>

    ) 
}

export default TestChild;